                        stack.append((ny, nx))
            comps.append((color, cells))

    def is_l(cells):
        ys = [y for y, x in cells]
        xs = [x for y, x in cells]
        return max(ys) > min(ys) and max(xs) > min(xs)

    # The large L is the color key; recolor the smaller L-shaped object to it.
    marker = max(
        ((color, cells) for color, cells in comps
         if color != 3 and len(cells) >= 8 and is_l(cells)),
        key=lambda item: len(item[1]),
        default=None
    )
    if marker is None:
        return out

