    targets = [(color, cells) for color, cells in comps
               if color != key_color and len(cells) >= 3 and is_l(cells)]
    if targets:
        # Among L-shaped components, choose the small one rather than the marker.
        _, cells = min(targets, key=lambda item: len(item[1]))
        for y, x in cells:
            out[y][x] = key_color
    return out
